// Curves computed from data for graphs: lowess, kernel density, and
// polynomial fits with their confidence bands. lowess and kdensity are
// compared with values generated by installed Stata.
import { invttail } from "./distributions.js";
import { density as normalDensity } from "./functions-normal.js";
import { percentile } from "./reports.js";

/**
 * Stata's lowess: for each point, a weighted regression of y on x over the
 * window of k observations on either side in x order, with tricube weights.
 * Returns the smoothed value for each input point, in input order.
 */
export function lowess(
  x,
  y,
  { bwidth = 0.8, mean = false, weight = true } = {},
) {
  const n = x.length,
    order = x.map((_, i) => i).sort((a, b) => x[a] - x[b] || a - b),
    xs = order.map((i) => x[i]),
    ys = order.map((i) => y[i]),
    k = Math.trunc((n * bwidth - 0.5) / 2),
    out = new Array(n);
  for (let i = 0; i < n; i++) {
    const first = Math.max(0, i - k),
      last = Math.min(n - 1, i + k),
      delta = 1.0001 * Math.max(xs[last] - xs[i], xs[i] - xs[first]);
    let sw = 0,
      swx = 0,
      swy = 0,
      swxx = 0,
      swxy = 0;
    for (let j = first; j <= last; j++) {
      const u = delta > 0 ? Math.abs(xs[j] - xs[i]) / delta : 0,
        w = weight ? (1 - u ** 3) ** 3 : 1;
      sw += w;
      swx += w * xs[j];
      swy += w * ys[j];
      swxx += w * xs[j] * xs[j];
      swxy += w * xs[j] * ys[j];
    }
    const mx = swx / sw,
      my = swy / sw,
      sxx = swxx - sw * mx * mx,
      slope = mean || !(sxx > 0) ? 0 : (swxy - sw * mx * my) / sxx;
    out[order[i]] = my + slope * (xs[i] - mx);
  }
  return out;
}

const SQRT5 = Math.sqrt(5);
export const KERNELS = {
  // Stata's Epanechnikov kernel has support sqrt(5) bandwidths wide.
  epanechnikov: (z) =>
    Math.abs(z) < SQRT5 ? (0.75 * (1 - (z * z) / 5)) / SQRT5 : 0,
  epan2: (z) => (Math.abs(z) < 1 ? 0.75 * (1 - z * z) : 0),
  gaussian: normalDensity,
  rectangle: (z) => (Math.abs(z) < 1 ? 0.5 : 0),
  triangle: (z) => (Math.abs(z) < 1 ? 1 - Math.abs(z) : 0),
  biweight: (z) => (Math.abs(z) < 1 ? (15 / 16) * (1 - z * z) ** 2 : 0),
};
/** Stata's default bandwidth: 0.9 min(sd, IQR/1.349) n^(-1/5). */
export function defaultBandwidth(values) {
  const n = values.length,
    sorted = [...values].sort((a, b) => a - b),
    mean = values.reduce((a, b) => a + b, 0) / n,
    sd = Math.sqrt(values.reduce((t, v) => t + (v - mean) ** 2, 0) / (n - 1)),
    iqr = percentile(sorted, 75) - percentile(sorted, 25);
  return (0.9 * Math.min(sd, iqr / 1.349)) / n ** 0.2;
}
export function kernelDensity(values, at, bandwidth, kernel = "epanechnikov") {
  const K = KERNELS[kernel],
    n = values.length;
  return at.map(
    (point) =>
      values.reduce((t, v) => t + K((point - v) / bandwidth), 0) /
      (n * bandwidth),
  );
}
/** The evaluation grid kdensity uses: n points from min - h to max + h. */
export function densityGrid(values, bandwidth, n) {
  const low = Math.min(...values) - bandwidth,
    high = Math.max(...values) + bandwidth;
  return Array.from({ length: n }, (_, k) =>
    // The last point is the upper end exactly, where bounded kernels reach 0.
    n > 1 ? (k === n - 1 ? high : low + ((high - low) * k) / (n - 1)) : low,
  );
}

/**
 * Least squares of y on 1, x, ..., x^degree. Returns predict(x) and
 * band(x, level): the confidence limits of the fitted mean.
 */
export function polynomialFit(x, y, degree) {
  const n = x.length,
    size = degree + 1,
    row = (v) => Array.from({ length: size }, (_, p) => v ** p),
    xtx = Array.from({ length: size }, () => new Array(size).fill(0)),
    xty = new Array(size).fill(0);
  x.forEach((v, i) => {
    const r = row(v);
    for (let a = 0; a < size; a++) {
      xty[a] += r[a] * y[i];
      for (let b = 0; b < size; b++) xtx[a][b] += r[a] * r[b];
    }
  });
  // Gauss-Jordan inverse; the systems here are two or three wide.
  const inverse = xtx.map((r, i) => [
    ...r,
    ...Array.from({ length: size }, (_, j) => Number(i === j)),
  ]);
  for (let c = 0; c < size; c++) {
    let pivot = c;
    for (let r = c + 1; r < size; r++)
      if (Math.abs(inverse[r][c]) > Math.abs(inverse[pivot][c])) pivot = r;
    [inverse[c], inverse[pivot]] = [inverse[pivot], inverse[c]];
    const d = inverse[c][c];
    if (!(Math.abs(d) > 0)) return null;
    for (let j = 0; j < 2 * size; j++) inverse[c][j] /= d;
    for (let r = 0; r < size; r++) {
      if (r === c) continue;
      const f = inverse[r][c];
      for (let j = 0; j < 2 * size; j++) inverse[r][j] -= f * inverse[c][j];
    }
  }
  const v = inverse.map((r) => r.slice(size)),
    b = v.map((r) => r.reduce((t, value, j) => t + value * xty[j], 0)),
    predict = (value) => row(value).reduce((t, r, p) => t + r * b[p], 0),
    rss = x.reduce((t, value, i) => t + (y[i] - predict(value)) ** 2, 0),
    df = n - size,
    s2 = df > 0 ? rss / df : 0;
  return {
    predict,
    band(value, level = 95) {
      const r = row(value),
        se = Math.sqrt(
          s2 *
            r.reduce(
              (t, a, i) => t + a * r.reduce((u, c, j) => u + v[i][j] * c, 0),
              0,
            ),
        ),
        critical = df > 0 ? invttail(df, (1 - level / 100) / 2) : 0,
        fitted = predict(value);
      return [fitted - critical * se, fitted + critical * se];
    },
  };
}

/** The five numbers of a box plot, with the values outside the whiskers. */
export function boxStatistics(values) {
  const sorted = [...values].sort((a, b) => a - b),
    q1 = percentile(sorted, 25),
    median = percentile(sorted, 50),
    q3 = percentile(sorted, 75),
    reach = 1.5 * (q3 - q1),
    inside = sorted.filter((v) => v >= q1 - reach && v <= q3 + reach);
  return {
    q1,
    median,
    q3,
    lower: inside.length ? inside[0] : q1,
    upper: inside.length ? inside.at(-1) : q3,
    outside: sorted.filter((v) => v < q1 - reach || v > q3 + reach),
  };
}
